import AppKit

// MARK: - OptionControl

/// Shared surface of the options-bar controls: a fixed intrinsic size, and a
/// `refresh()` that re-reads the descriptor closures (value and enabled
/// state). A disabled control dims to 42% and ignores input; the closures
/// stay the single source of truth — no control stores a value.
protocol OptionControl: NSView {
    func refresh()
}

// MARK: - OptionFieldControl

/// A borderless NSTextField gives no focus callback; this one reports
/// becoming first responder so its owner can swap the formatted rest
/// display ("24 px") for the bare editable number.
private final class FocusReportingTextField: NSTextField {
    var onFocus: (() -> Void)?

    override init(frame frameRect: NSRect) {
        super.init(frame: frameRect)
    }

    @available(*, unavailable)
    required init?(coder: NSCoder) {
        fatalError("FocusReportingTextField does not support NSCoder")
    }

    override func becomeFirstResponder() -> Bool {
        let accepted = super.becomeFirstResponder()
        if accepted { onFocus?() }
        return accepted
    }
}

/// Numeric option field: a bordered container around an embedded borderless
/// mono field. At rest it shows the formatted value plus unit; while editing
/// it shows the bare number. Enter and end-editing commit (clamped to the
/// descriptor's range), Escape reverts. A non-empty `quick` list appends a
/// chevron zone on the right that pops a menu of those preset values.
final class OptionFieldControl: NSView, NSTextFieldDelegate, OptionControl {
    private let fixedWidth: CGFloat
    private let unit: String
    private let decimals: Int
    private let lower: Double
    private let upper: Double
    private let quick: [Double]
    private let read: () -> Double
    private let write: (Double) -> Void
    private let enabled: () -> Bool
    private let onEdit: () -> Void
    private let field = FocusReportingTextField(frame: .zero)
    private var isActive = true
    /// True while an Enter/Escape hand-off is resigning first responder, so
    /// the resulting end-editing notification doesn't commit a second time.
    private var finishing = false

    /// Width the quick-pick chevron zone adds beyond the text width.
    private static let quickZoneWidth: CGFloat = 15

    init(
        width: CGFloat, unit: String, decimals: Int, min: Double, max: Double,
        quick: [Double] = [],
        read: @escaping () -> Double, write: @escaping (Double) -> Void,
        enabled: @escaping () -> Bool, onEdit: @escaping () -> Void
    ) {
        self.fixedWidth = width
        self.unit = unit
        self.decimals = decimals
        self.lower = min
        self.upper = max
        self.quick = quick
        self.read = read
        self.write = write
        self.enabled = enabled
        self.onEdit = onEdit
        super.init(frame: .zero)
        wantsLayer = true
        field.isBezeled = false
        field.isBordered = false
        field.drawsBackground = false
        field.focusRingType = .none
        field.font = DS.mono(11)
        field.textColor = DS.textStrong
        field.usesSingleLineMode = true
        field.lineBreakMode = .byClipping
        field.delegate = self
        field.onFocus = { [weak self] in self?.beginBareEditing() }
        addSubview(field)
        refresh()
    }

    @available(*, unavailable)
    required init?(coder: NSCoder) {
        fatalError("OptionFieldControl does not support NSCoder")
    }

    override var isFlipped: Bool { true }

    private var quickZone: CGFloat {
        quick.isEmpty ? 0 : Self.quickZoneWidth
    }

    override var intrinsicContentSize: NSSize {
        NSSize(width: fixedWidth + quickZone, height: DS.controlHeight)
    }

    override func layout() {
        super.layout()
        let height = ceil(DS.mono(11).boundingRectForFont.height)
        field.frame = NSRect(
            x: 7, y: floor((bounds.height - height) / 2),
            width: max(0, bounds.width - 14 - quickZone), height: height)
    }

    override func draw(_ dirtyRect: NSRect) {
        let path = NSBezierPath(
            roundedRect: bounds.insetBy(dx: 0.5, dy: 0.5),
            xRadius: DS.controlRadius, yRadius: DS.controlRadius)
        NSColor.controlBackgroundColor.setFill()
        path.fill()
        DS.border.setStroke()
        path.stroke()

        guard !quick.isEmpty else { return }
        if let icon = NSImage(
            systemSymbolName: "chevron.down", accessibilityDescription: "Quick values")?
            .withSymbolConfiguration(NSImage.SymbolConfiguration(pointSize: 8, weight: .semibold))
        {
            let tinted = icon.tinted(with: DS.textMuted)
            let size = tinted.size
            tinted.draw(
                in: NSRect(
                    x: bounds.width - 5 - size.width, y: (bounds.height - size.height) / 2,
                    width: size.width, height: size.height))
        } else {
            let attributes: [NSAttributedString.Key: Any] = [
                .font: DS.sans(9), .foregroundColor: DS.textMuted,
            ]
            let size = "▾".size(withAttributes: attributes)
            "▾".draw(
                at: NSPoint(
                    x: bounds.width - 5 - size.width, y: (bounds.height - size.height) / 2),
                withAttributes: attributes)
        }
    }

    override func mouseDown(with event: NSEvent) {
        // The 7pt margins around the embedded field still read as the
        // control; a click anywhere on it starts editing — except the
        // quick-pick chevron zone, which pops the preset menu.
        guard isActive else { return }
        let point = convert(event.locationInWindow, from: nil)
        if !quick.isEmpty, point.x >= bounds.width - Self.quickZoneWidth {
            showQuickMenu()
            return
        }
        window?.makeFirstResponder(field)
    }

    /// The chevron's preset menu: each value formatted exactly as the field
    /// shows it at rest, checkmarked on the current value.
    private func showQuickMenu() {
        if field.currentEditor() != nil { finishEditing(commit: true) }
        let menu = NSMenu()
        let current = read()
        for (index, value) in quick.enumerated() {
            let item = NSMenuItem(
                title: String(format: "%.\(decimals)f", value) + unit,
                action: #selector(quickPicked(_:)), keyEquivalent: "")
            item.target = self
            item.tag = index
            item.state = abs(value - current) < 0.0001 ? .on : .off
            menu.addItem(item)
        }
        menu.minimumWidth = bounds.width
        menu.popUp(positioning: nil, at: NSPoint(x: 0, y: bounds.height + 2), in: self)
    }

    @objc private func quickPicked(_ sender: NSMenuItem) {
        guard quick.indices.contains(sender.tag) else { return }
        let value = Swift.min(upper, Swift.max(lower, quick[sender.tag]))
        // Same unchanged-value guard as typed commits: setters that do real
        // work (the selection-morphology fields) must not re-fire on a
        // pick of the value already showing.
        guard abs(value - read()) > 0.0001 else { return }
        write(value)
        onEdit()
        field.stringValue = restText()
    }

    func refresh() {
        isActive = enabled()
        alphaValue = isActive ? 1 : 0.42
        field.isEditable = isActive
        field.isSelectable = isActive
        guard field.currentEditor() == nil else { return }
        field.stringValue = restText()
    }

    // MARK: Editing

    private func restText() -> String {
        bareText() + unit
    }

    private func bareText() -> String {
        String(format: "%.\(decimals)f", read())
    }

    private func beginBareEditing() {
        field.stringValue = bareText()
        if let editor = field.currentEditor() as? NSTextView {
            editor.drawsBackground = false
        }
        field.currentEditor()?.selectAll(nil)
    }

    private func parsedValue(_ text: String) -> Double? {
        var trimmed = text.trimmingCharacters(in: .whitespaces)
        let bareUnit = unit.trimmingCharacters(in: .whitespaces)
        if !bareUnit.isEmpty, trimmed.hasSuffix(bareUnit) {
            trimmed = String(trimmed.dropLast(bareUnit.count))
                .trimmingCharacters(in: .whitespaces)
        }
        return Double(trimmed)
    }

    private func commitCurrentText() {
        guard let value = parsedValue(field.stringValue) else { return }
        let clamped = Swift.min(upper, Swift.max(lower, value))
        // An unchanged value is not an edit: some setters do real work on
        // write (the selection-morphology fields apply their op), so merely
        // focusing a field and tabbing away must not fire them.
        guard abs(clamped - read()) > 0.0001 else { return }
        write(clamped)
        onEdit()
    }

    private func finishEditing(commit: Bool) {
        finishing = true
        if commit { commitCurrentText() }
        window?.makeFirstResponder(window?.contentView)  // #60
        finishing = false
        field.stringValue = restText()
    }

    func control(
        _ control: NSControl, textView: NSTextView, doCommandBy commandSelector: Selector
    ) -> Bool {
        if commandSelector == #selector(NSResponder.insertNewline(_:)) {
            finishEditing(commit: true)
            return true
        }
        if commandSelector == #selector(NSResponder.cancelOperation(_:)) {
            finishEditing(commit: false)
            return true
        }
        return false
    }

    func controlTextDidEndEditing(_ obj: Notification) {
        // Click-away and Tab land here directly; Enter/Escape came through
        // finishEditing and already handled the commit.
        guard !finishing else { return }
        commitCurrentText()
        field.stringValue = restText()
    }
}

// MARK: - OptionDisplayControl

/// Read-only mono readout (the eyedropper's hex value): no chrome, just the
/// text vertically centered in the control height.
final class OptionDisplayControl: NSView, OptionControl {
    private let fixedWidth: CGFloat
    private let read: () -> String
    private let enabled: () -> Bool
    private(set) var text = ""

    init(width: CGFloat, read: @escaping () -> String, enabled: @escaping () -> Bool) {
        self.fixedWidth = width
        self.read = read
        self.enabled = enabled
        super.init(frame: .zero)
        wantsLayer = true
        refresh()
    }

    @available(*, unavailable)
    required init?(coder: NSCoder) {
        fatalError("OptionDisplayControl does not support NSCoder")
    }

    override var isFlipped: Bool { true }

    override var intrinsicContentSize: NSSize {
        NSSize(width: fixedWidth, height: DS.controlHeight)
    }

    func refresh() {
        text = read()
        alphaValue = enabled() ? 1 : 0.42
        needsDisplay = true
    }

    override func draw(_ dirtyRect: NSRect) {
        let attributes: [NSAttributedString.Key: Any] = [
            .font: DS.mono(11), .foregroundColor: DS.textStrong,
        ]
        let size = text.size(withAttributes: attributes)
        text.draw(
            at: NSPoint(x: 0, y: (bounds.height - size.height) / 2),
            withAttributes: attributes)
    }
}

// MARK: - OptionPopupControl

/// Field-styled popup: the current item in mono with an up/down chevron at
/// the right; clicking pops an NSMenu with a checkmark on the current item.
final class OptionPopupControl: NSView, OptionControl {
    private let fixedWidth: CGFloat
    private let items: [String]
    private let read: () -> Int
    private let write: (Int) -> Void
    private let enabled: () -> Bool
    private let onEdit: () -> Void
    private var isActive = true
    private var hovered = false

    init(
        width: CGFloat, items: [String], read: @escaping () -> Int,
        write: @escaping (Int) -> Void, enabled: @escaping () -> Bool,
        onEdit: @escaping () -> Void
    ) {
        self.fixedWidth = width
        self.items = items
        self.read = read

import AppKit

/// The editor's document window, and the two things it decides: where a bare
/// Space goes (spec §11 K-1, kpgalligan/framejob#35), and when text gives
/// the keys back (K-4, `TextFocus` below), which it asks first.
///
/// **Space is the transport's unless the first responder is typing or claims
/// it.** The window routes a bare Space key-DOWN (⇧ and ⇪ allowed, any other
/// modifier untouched) BEFORE dispatch, because dispatch is what beeped when
/// the WINDOW was first responder — as it still can be when a focused view is
/// removed (`OptionFieldControl.finishEditing` hands focus to the content
/// view since #60): `NSWindow.keyDown` forwards to nothing, and
/// `NSResponder.noResponder(for:)` beeps — the key never reached
/// `EditorViewController.keyDown`.
///
/// Three claimants keep the key:
/// - an editable `NSTextView` — every field editor, the Text tab's area, the
///   canvas's inline editor, the Media tab's search field — so a Space is
///   TYPED there;
/// - an `NSButton` (which covers `NSPopUpButton`) or an `NSSegmentedControl`:
///   they press on Space by AppKit's own convention, reachable only under
///   Full Keyboard Access, and an accessibility user keeps it;
/// - the canvas overlay (`CanvasOverlayView`), whose own Space arms a pan and
///   toggles play on key-UP (`PreviewCanvasView.handleKeyUp`).
/// And nothing is taken while a sheet is attached. An auto-repeat of a Space
/// the window took is swallowed. A non-editable field editor (a selectable
/// label), a slider, the window itself and every custom inspector control
/// are the transport's.
///
/// `handleEditorCharacter`'s `case " "` in `EditorViewController` stays for
/// the preview panel's forward (`PreviewWindowController.keyDown`) and is
/// dead for this window.
enum SpaceKeyRoute: Equatable { case transport, held, responder }

enum SpaceKey {
    /// nil unless `event` is a key-DOWN of keyCode 49 whose device-independent
    /// flags ⊆ [.shift, .capsLock]. Pure: reads only its arguments.
    static func route(
        _ event: NSEvent, firstResponder: NSResponder?, sheetAttached: Bool
    ) -> SpaceKeyRoute? {
        guard event.type == .keyDown, event.keyCode == 49 else { return nil }
        let flags = event.modifierFlags.intersection(.deviceIndependentFlagsMask)
        guard flags.subtracting([.shift, .capsLock]).isEmpty else { return nil }
        if sheetAttached { return .responder }
        if (firstResponder as? NSTextView)?.isEditable == true { return .responder }
        if firstResponder is NSButton || firstResponder is NSSegmentedControl
            || firstResponder is CanvasOverlayView
        {
            return .responder
        }
        if event.isARepeat { return .held }
        return .transport
    }
}

/// When the editor window takes the keys back from text (spec §11 K-4):
/// typing is focus-averse. Only a click, or a command that exists to type,
/// gives text the keys; a click outside it, Tab (unless Full Keyboard Access
/// is on), and Return in a one-line field hand them back to the content
/// view — the root that holds the bare-key map — BEFORE dispatch, so Space
/// plays the moment typing ends.
///
/// Before dispatch because of what dispatch did: a click on the timeline,
/// which refuses first responder, left the field editor attached, and
/// AppKit's own Return re-selected the field after its commit — both behind
/// no focus ring, so the next Space was typed into a field that looked left.
/// Each field still commits through its own end-of-editing path, as on any
/// blur. Pure, so a probe can ask it.
enum TextFocus {
    /// The text taking keys when `responder` is editable text — every field
    /// editor, the Text tab's area, the canvas's inline editor, the
    /// composer — else nil.
    static func typing(_ responder: NSResponder?) -> NSTextView? {
        guard let text = responder as? NSTextView, text.isEditable else { return nil }
        return text
    }

    /// Where a click keeps the typing: a field editor's field, or the
    /// `OptionFieldControl` that frames it (its margins and chevron are the
    /// field's own); else the text view's scroll view, so a scroller is
    /// inside; else the text view.
    static func host(of text: NSTextView) -> NSView {
        if text.isFieldEditor, let field = text.delegate as? NSView {
            return (field.superview as? OptionFieldControl) ?? field
        }
        return text.enclosingScrollView ?? text
    }

    /// True when the key-down `event` leaves `text`: Tab or ⇧Tab in any
    /// text, unless `fullKeyboardAccess` — then Tab is AppKit's key-view
    /// loop, how such a user reaches a control (K-1's exception); Return or
    /// keypad Enter in a field editor (⇧ ⇪, and the keypad and fn flags,
    /// allowed). ⌃Tab, ⌥Return and ⌘ are AppKit's; a multi-line view routes
    /// its own Return (`TextEditKey`). Never while an input method has
    /// marked text.
    static func leavesOnKey(
        _ event: NSEvent, in text: NSTextView, fullKeyboardAccess: Bool
    ) -> Bool {
        guard event.type == .keyDown, !text.hasMarkedText() else { return false }
        let flags = event.modifierFlags.intersection(.deviceIndependentFlagsMask)
        switch event.keyCode {
        case 48:
            return !fullKeyboardAccess && flags.subtracting([.shift, .capsLock]).isEmpty
        case 36, 76:
            return text.isFieldEditor
                && flags.subtracting([.shift, .capsLock, .numericPad, .function]).isEmpty
        default:
            return false
        }
    }

    /// True when a mouse-down whose content hit is `hit` leaves `text`: a
    /// hit outside its host. nil — the click is outside the content view,
    /// on the title bar — never leaves.
    static func leavesOnClick(hit: NSView?, in text: NSTextView) -> Bool {
        guard let hit else { return false }
        return !hit.isDescendant(of: host(of: text))
    }
}

/// The bare-key map's modifier rule, read by `handleEditorKey` (#61).
enum EditorKey {
    /// Device-independent part of `flags` minus [.shift, .capsLock] must be empty, except that on a
    /// function-key scalar (0xF700...0xF8FF) .numericPad and .function are also allowed. ⌘ ⌥ ⌃ .help never. Pure.
    static func isBare(_ flags: NSEvent.ModifierFlags, scalar: UInt32) -> Bool {
        var allowed: NSEvent.ModifierFlags = [.shift, .capsLock]
        if (0xF700...0xF8FF).contains(scalar) { allowed.formUnion([.numericPad, .function]) }
        return flags.intersection(.deviceIndependentFlagsMask).subtracting(allowed).isEmpty
    }
}

final class EditorWindow: NSWindow {
    /// Forwards to `super` unchanged. Declared because the unavailable coder
    /// init below is a designated initializer, and declaring one stops Swift
    /// inheriting `NSWindow`'s — without it `EditorWindowController`'s
    /// construction does not typecheck.
    override init(
        contentRect: NSRect, styleMask style: NSWindow.StyleMask,
        backing backingStoreType: NSWindow.BackingStoreType, defer flag: Bool
    ) {
        super.init(
            contentRect: contentRect, styleMask: style, backing: backingStoreType, defer: flag)
    }

    @available(*, unavailable)
    required init?(coder: NSCoder) {
        fatalError("EditorWindow does not support NSCoder")
    }

    override func sendEvent(_ event: NSEvent) {
        // A key that leaves is spent; a click that leaves is then delivered.
        if leaveText(for: event), event.type == .keyDown { return }
        switch SpaceKey.route(
            event, firstResponder: firstResponder, sheetAttached: attachedSheet != nil)
        {
        case .transport:
            guard let editor = contentViewController as? EditorViewController else {
                super.sendEvent(event)
                return
            }
            editor.playPause(nil)
        case .held:
            return
        case .responder, nil:
            super.sendEvent(event)
        }
    }

    /// `TextFocus`'s rule applied: true when `event` left the text, first
    /// responder now the content view. A field that refuses to resign keeps
    /// the event, and nothing is taken while a sheet is attached.
    private func leaveText(for event: NSEvent) -> Bool {
        guard attachedSheet == nil, let text = TextFocus.typing(firstResponder),
              let content = contentView
        else { return false }
        let leaves: Bool
        switch event.type {
        case .keyDown:
            leaves = TextFocus.leavesOnKey(
                event, in: text, fullKeyboardAccess: NSApp.isFullKeyboardAccessEnabled)
        case .leftMouseDown, .rightMouseDown, .otherMouseDown:
            let point = content.superview?.convert(event.locationInWindow, from: nil)
                ?? event.locationInWindow
            leaves = TextFocus.leavesOnClick(hit: content.hitTest(point), in: text)
        default:
            leaves = false
        }
        return leaves && makeFirstResponder(content)
    }
}
        guard let anchor = sender as? NSView else {
            NSSound.beep()
            return
        }
        menu.popUp(
            positioning: nil, at: NSPoint(x: 0, y: anchor.bounds.height + 4), in: anchor)
    }

    // MARK: - Keyboard (spec §9, the part the editor owns)

    override func keyDown(with event: NSEvent) {
        if handleEditorKey(event) { return }
        super.keyDown(with: event)
    }

    /// Bare keys only, and never while text is being edited — a modifier-less
    /// letter must not be stolen from the timecode field or (later) an inline
    /// text clip. Everything with a modifier arrives as a menu key
    /// equivalent instead, which is also where it gets validated.
    ///
    /// Internal rather than private since road map 2's phase 8b: the preview
    /// window is a second window, so its content view is not in this
    /// controller's responder chain and has nowhere to send a bare Space or
    /// J/K/L. It hands the event here rather than carrying a second copy of the
    /// map (`PreviewWindowController.swift`), which is the one thing that could
    /// make the two windows' transports disagree.
    func handleEditorKey(_ event: NSEvent) -> Bool {
        if view.window?.firstResponder is NSText { return false }
        // And never while a sheet is attached — the same invariant
        // `validateUserInterfaceItem` opens with below, because this map is
        // not only transport: `t` adds a text clip, `w`/`e` trim, `m` marks,
        // `,`/`.` nudge, `i`/`o` write the range. A sheet captures a project
        // handle and reads it again later, so the document must not move
        // under it. Until phase 8b that held here for free and needed no line,
        // since a sheet takes the editor window's key status and this method
        // was simply unreachable while one was up. But a sheet is WINDOW-modal
        // rather than application-modal (measured: with one attached
        // `NSApp.modalWindow` is nil, and the preview panel is visible and
        // `canBecomeKey`), and the panel forwards its bare keys straight here,
        // where no validator stands — `t` added a text clip behind an open
        // export card that had already captured the project it was about to
        // write, and Remove Silences, which computes its spans ONCE, would
        // have rippled ranges that no longer described the timeline. The guard
        // belongs beside the key map rather than in the panel: both windows
        // inherit it, no second copy can drift, and the editor's own path pays
        // nothing for a case it cannot reach.
        if view.window?.attachedSheet != nil { return false }
        let flags = event.modifierFlags.intersection(.deviceIndependentFlagsMask)
        guard let scalar = event.charactersIgnoringModifiers?.unicodeScalars.first else {
            return false
        }
        guard EditorKey.isBare(flags, scalar: scalar.value) else { return false }
        let shift = flags.contains(.shift)
        switch scalar.value {
        case UInt32(NSLeftArrowFunctionKey):
            stepFrames(shift ? -10 : -1)
        case UInt32(NSRightArrowFunctionKey):
            stepFrames(shift ? 10 : 1)
        case UInt32(NSUpArrowFunctionKey):
            previousEditPoint(nil)
        case UInt32(NSDownArrowFunctionKey):
            nextEditPoint(nil)
        case UInt32(NSHomeFunctionKey):
            goToStart(nil)
        case UInt32(NSEndFunctionKey):
            goToEnd(nil)
        case 27: return deselectActionCommand()
        default:
            return handleEditorCharacter(Character(scalar), shift: shift)
        }
        return true
    }

    /// Compared as a lowercased STRING, not a `Character`: lowercasing is not
    /// one-to-one in every locale (a Turkish "İ" becomes two scalars), and
    /// `Character(String)` traps on anything but exactly one.
    private func handleEditorCharacter(_ character: Character, shift: Bool) -> Bool {
        switch character.lowercased() {
        case " ":
            playPause(nil)
        case "j":
            shuttle(forward: false)
        case "k":
            playback.pause()
        case "l":
            shuttle(forward: true)
        case "i":
            setInPoint(nil)
        case "o":
            setOutPoint(nil)
        case "n":
            toggleSnapping(nil)
        case "m":
            addMarker(nil)
        case "w":
            trimStartToPlayhead(nil)
        case "e":
            trimEndToPlayhead(nil)
        case "t":
            addTextClip(nil)
        case "c":
            toggleCropMode(nil)
        case "z" where shift:
            fitTimeline(nil)
        // Bare Z arms the canvas region mode (road map 2's phase 3b, spec §9),
        // and it must stay BELOW the ⇧Z case: a `switch` matches in source
        // order, so a bare "z" above it would swallow Fit Timeline silently.
        // The command itself toggles, so Z is also the way back out
        // (EditorViewController+ZoomRegion.swift).
        case "z":
            zoomToRegion(nil)
        // ⇧ is still applied to `charactersIgnoringModifiers`, so ⇧, arrives
        // as "<" on a US layout — both spellings mean the same nudge.
        case ",", "<":
            nudgeSelection(frames: shift ? -10 : -1)
        case ".", ">":
            nudgeSelection(frames: shift ? 10 : 1)
        default:
            return false
        }
        return true
    }

    private func stepFrames(_ count: Int) {
        guard let document = document else { return }
        playback.stepFrames(count, fps: document.editedProject.snapshot.canvas.fps)
        document.playhead = playback.currentTime
        refreshTimecode()
    }

    // MARK: - Clip, track and marker actions
    //
    // One-line forwards into `EditorViewController+Timeline.swift`, which owns
    // the bodies (app/CLAUDE.md: this file stays wiring).

    @objc func splitAtPlayhead(_ sender: Any?) { splitAtPlayheadCommand() }
    @objc func trimStartToPlayhead(_ sender: Any?) { trimToPlayhead(.start) }
    @objc func trimEndToPlayhead(_ sender: Any?) { trimToPlayhead(.end) }
    @objc func deleteClips(_ sender: Any?) { deleteSelection() }
    @objc func rippleDeleteClips(_ sender: Any?) { rippleDeleteSelection() }
    @objc func duplicateClips(_ sender: Any?) { duplicateSelection() }
/// a destructive or a tertiary one, and on most sheets it would sit under a
/// footnote besides. It takes no key equivalent, which is the other half
/// of the same point — Return belongs to `apply` and Escape to `cancel`, and a
/// row with two Returns has none.
///
/// Its one caller is the export sheet's "Add to Queue" (road map 2's phase 7e,
/// built and passed in `ExportSheetController.loadView`) — the shipped example
/// to read before a second dialog takes the slot. The parameter landed a wave
/// AHEAD of that button, alone, because this file is shared by every dialog in
/// the app and a change to it is worth making where the type checker can see
/// every existing call is unchanged; it defaults to nil, so every dialog but
/// the export card still asks for the two-button row it always had.
///
/// **Every `leading` view resists compression at `.defaultLow`**, below the
/// buttons' default 750, so a long footnote gives way before a button and the
/// row has one answer instead of two tied ones (#141; a divergence from
/// Rasterize's copy).
func makeButtonRow(
    cancel: NSButton, apply: NSButton, secondary: NSButton? = nil, leading: [NSView] = []
) -> NSStackView {
    cancel.keyEquivalent = "\u{1b}"
    apply.keyEquivalent = "\r"
    for view in leading {
        view.setContentCompressionResistancePriority(.defaultLow, for: .horizontal)
    }
    let spacer = NSView()
    spacer.setContentHuggingPriority(.defaultLow - 1, for: .horizontal)
    let trailing: [NSView] = secondary.map { [$0, cancel, apply] } ?? [cancel, apply]
    let row = NSStackView(views: leading + [spacer] + trailing)
    row.orientation = .horizontal
    row.alignment = .centerY
