        NSRect(x: half, y: 0, width: half, height: half).fill()
        NSRect(x: 0, y: half, width: half, height: half).fill()
        read().setFill()
        bounds.fill()
        NSGraphicsContext.current?.restoreGraphicsState()
        DS.borderStrong.setStroke()
        path.stroke()
    }
