    /// property would be read as an override of it.
    private let isLive: () -> Bool
    private let onEdit: () -> Void
    private var placeholder: String?

    override class var cellClass: AnyClass? {
        get { InspectorNameFieldCell.self }
        set {}
    }

    override var alignmentRectInsets: NSEdgeInsets { NSEdgeInsets() }

    override var placeholderString: String? {
        get { placeholder }
        set {
            placeholder = newValue
            setAccessibilityPlaceholderValue(newValue)
            needsDisplay = true
        }
    }

    override var placeholderAttributedString: NSAttributedString? {
        get { placeholderString.map { NSAttributedString(string: $0) } }
        set { placeholderString = newValue?.string }
    }

    override func textDidChange(_ notification: Notification) {
        super.textDidChange(notification)
        needsDisplay = true
    }

    init(
        read: @escaping () -> String, write: @escaping (String) -> Void,
        enabled: @escaping () -> Bool, onEdit: @escaping () -> Void
    ) {
        self.read = read
        self.write = write
        self.isLive = enabled
        self.onEdit = onEdit
        super.init(frame: .zero)
        isBezeled = false
        isBordered = false
        drawsBackground = false
        focusRingType = .none
        textColor = DS.textStrong
        font = DS.sans(11)
        usesSingleLineMode = true
        cell?.isScrollable = true
        lineBreakMode = .byTruncatingTail
        heightAnchor.constraint(equalToConstant: DS.controlHeight).isActive = true
        delegate = self
        refresh()
    }

    @available(*, unavailable)
    required init?(coder: NSCoder) {
        fatalError("InspectorNameField does not support NSCoder")
    }

    func refresh() {
        let active = isLive()
        alphaValue = active ? 1 : 0.42
        isEditable = active
        isSelectable = active
        // Skipped while the field is being typed into, or the value it is
        // about to commit would be overwritten by the one it replaces.
        guard currentEditor() == nil else { return }
        let value = read()
        if stringValue != value { stringValue = value }
    }

    func controlTextDidEndEditing(_ obj: Notification) {
        let value = stringValue
        if value != read() {
            write(value)
            onEdit()
        }
        // Re-read directly rather than through `refresh()`: every refresh the
        // commit just ran was skipped, because the field editor is still
        // attached here, so the field would go on showing what was typed
        // (blank after a clear, padded text after a padded rename, blank on a
        // clip whose empty commit sent nothing) while the model holds the
        // trimmed name or the fallback. The timecode field's beep path sets
        // itself the same way.
        let now = read()
        if stringValue != now { stringValue = now }
    }
}

